    "faqs": [
      {
        "q": "What is WordPress website development?",
        "a": "It is the process of creating or customising a website using WordPress, including its pages, theme, content structure, plugins, and agreed functionality."
      },
      {
        "q": "Is WordPress suitable for a business website?",
        "a": "WordPress can be suitable for many business websites, including company profiles, service websites, blogs, and selected e-commerce projects. The best platform depends on your required functionality, technical needs, budget, and maintenance capacity."
      },
      {
        "q": "Can you build a website from scratch using WordPress?",
        "a": "Yes. We can plan and develop a new WordPress website within an agreed scope. The exact level of customisation depends on the project's requirements and selected technical approach."
      },
      {
        "q": "Can you customise an existing WordPress theme?",
        "a": "Yes. We can configure and customise a suitable theme. The amount of customisation depends on the theme, its licence, compatibility, and whether additional development is required."
      },
      {
        "q": "Do you use Elementor?",
        "a": "Elementor may be used where it suits the project. We can also consider the WordPress block editor or other appropriate tools. The selection depends on editing needs, performance, compatibility, and licence costs."
      },
      {
        "q": "Can you create an e-commerce website with WordPress?",
        "a": "Yes. WordPress can support e-commerce through suitable solutions such as WooCommerce. Product catalogue size, checkout, payment gateways, shipping, tax settings, and other features must be defined in the scope."
      },
      {
        "q": "Will I be able to update my website myself?",
        "a": "WordPress allows authorised users to manage supported pages and content. We can provide handover guidance for the features included in your website."
      },
      {
        "q": "Will you provide domain and hosting?",
        "a": "Domain and hosting can be coordinated as part of the project where agreed. Registration, hosting subscriptions, renewals, and related third-party costs are separate unless explicitly included."
      },
      {
        "q": "Will my website be mobile-friendly?",
        "a": "We plan responsive layouts and test the agreed pages across common device sizes. Specific behaviour can vary with third-party tools and embedded content."
      },
      {
        "q": "Will you install SEO plugins?",
        "a": "Suitable SEO plugins can be configured where included and compatible with the website. Installing a plugin alone does not guarantee rankings or organic traffic."
      },
      {
        "q": "Will my WordPress website be secure?",
        "a": "We can configure agreed foundational security measures. No website can be guaranteed completely secure; hosting, updates, access controls, plugin quality, and ongoing maintenance also matter."
      },
      {
        "q": "Can you migrate my existing WordPress website?",
        "a": "Migration may be possible after reviewing the current hosting environment, files, database, domain access, and technical condition. Some migrations require additional work."
      },
      {
        "q": "Can you connect my website to a CRM or booking tool?",
        "a": "We can assess and configure supported integrations where access and compatibility are available. Complex APIs and advanced automation may require separate development."
      },
      {
        "q": "Do you provide website maintenance?",
        "a": "Maintenance can be provided under a separate agreement or a clearly defined maintenance scope. Updates, backups, monitoring, content changes, and support frequency should be specified in advance."
      },
      {
        "q": "How long does WordPress website development take?",
        "a": "The timeline depends on the number of pages, content readiness, design complexity, integrations, revisions, and client approvals. We will provide an estimated timeline after defining the scope."
      },
      {
        "q": "How much does a WordPress website cost?",
        "a": "The cost depends on page count, customisation, functionality, content, integrations, and third-party requirements. E-COMET OUTVERSE does not display public package prices on this page. We discuss your needs and provide a custom quotation."
      }
    ],
