    "faqs": [
      {
        "q": "What is Shopify store development?",
        "a": "It is the process of building and configuring an online store using Shopify, including its design, pages, products, collections, settings, and agreed integrations."
      },
      {
        "q": "Is Shopify suitable for a new business?",
        "a": "Shopify can suit many businesses launching an online store. Suitability depends on the product range, required features, budget, selling region, and operating requirements."
      },
      {
        "q": "Can you build my Shopify store from scratch?",
        "a": "Yes. We can plan and develop a new Shopify store within an agreed scope, subject to account readiness, platform capabilities, and required third-party approvals."
      },
      {
        "q": "Can you customise my Shopify theme?",
        "a": "Yes. We can customise a suitable theme within its available capabilities. More advanced design requirements may need custom development or a different theme."
      },
      {
        "q": "Can you upload my products?",
        "a": "Product setup and uploads can be included within an agreed product quantity. Product data, prices, variants, images, inventory information, and factual claims must be provided or approved by your business."
      },
      {
        "q": "Can you integrate a payment gateway?",
        "a": "We can assist with configuring supported payment providers. Availability, account approval, verification, fees, and settlement arrangements depend on the provider and your business eligibility."
      },
      {
        "q": "Can you configure shipping and taxes?",
        "a": "We can help configure supported settings using your approved requirements. Shipping availability and tax treatment depend on location, platform capabilities, provider arrangements, and applicable rules. Tax decisions should be confirmed with a qualified professional."
      },
      {
        "q": "Can I connect my Shopify store with Amazon and Flipkart?",
        "a": "Potentially, through supported integrations or suitable third-party tools. Inventory synchronisation, order routing, product mapping, and ongoing management require separate assessment and clear scope."
      },
      {
        "q": "Will my store be mobile-friendly?",
        "a": "We plan responsive storefront layouts and test the agreed pages across common device sizes. Specific behaviour may depend on the selected theme and third-party apps."
      },
      {
        "q": "Can you connect Shopify to email marketing or a CRM?",
        "a": "We can assess supported integrations based on your chosen tools, account access, permissions, and requirements. Advanced custom integrations may need separate development."
      },
      {
        "q": "Will my Shopify store be SEO-friendly?",
        "a": "We can configure relevant page metadata, product structure, image alt text, and other agreed SEO settings. These measures do not guarantee rankings or organic traffic."
      },
      {
        "q": "Do you provide product photography?",
        "a": "Product photography can be arranged as a separate service or included in a custom project scope where agreed."
      },
      {
        "q": "Do you provide ongoing store management?",
        "a": "Yes, ongoing work can be discussed separately under Shopify Store Management. Development alone does not automatically include routine product updates, order handling, customer service, or ongoing optimisation."
      },
      {
        "q": "Can you redesign my existing Shopify store?",
        "a": "Yes. We can review the existing store and propose design, structure, or functionality improvements based on its current theme, apps, and technical limitations."
      },
      {
        "q": "How long does Shopify store development take?",
        "a": "The timeline depends on catalogue size, content readiness, design complexity, integrations, approvals, and revision requirements. We will estimate the timeline after defining the project scope."
      },
      {
        "q": "How much does Shopify store development cost?",
        "a": "The cost depends on the number of pages and products, design requirements, integrations, app requirements, and project complexity. E-COMET OUTVERSE does not display public package prices on this page. We discuss your requirements and provide a custom quotation."
      }
    ],
