    "integratedSolutions": {
      "heading": "8. INTEGRATED DIGITAL SOLUTIONS",
      "headline": "Connect Your WooCommerce Store to a Bigger Digital Strategy.",
      "description": "Your online store can become part of a wider digital business system. E-COMET OUTVERSE can coordinate relevant services according to your business objectives.",
      "cta": "Build My Integrated Digital Plan"
    },
    "faqs": [
      {
        "q": "What is WooCommerce store development?",
        "a": "It is the process of building and configuring an online store using WooCommerce on WordPress, including product pages, catalogue structure, cart, checkout, and agreed integrations."
      },
      {
        "q": "Is WooCommerce suitable for my business?",
        "a": "WooCommerce can suit many product-based businesses and selected digital commerce models. Suitability depends on the required features, hosting, technical resources, budget, and ongoing maintenance needs."
      },
      {
        "q": "Can you build a WooCommerce store from scratch?",
        "a": "Yes. We can plan and develop a new store within the agreed scope, subject to hosting readiness, platform compatibility, and third-party requirements."
      },
      {
        "q": "Can you add an online store to my existing WordPress website?",
        "a": "Potentially, yes. We first assess the current theme, plugins, hosting, and website structure to determine the appropriate implementation."
      },
      {
        "q": "Can you upload my products?",
        "a": "Yes, product setup can be included within an agreed catalogue quantity. Your business must provide or approve accurate product information, prices, images, inventory details, and relevant claims."
      },
      {
        "q": "Can you integrate an Indian payment gateway?",
        "a": "We can assess and configure supported payment gateway plugins according to your requirements. Provider availability, approval, verification, fees, and settlement depend on the provider and merchant account."
      },
      {
        "q": "Can you configure shipping for India or international markets?",
        "a": "We can configure supported shipping methods and suitable integrations within the agreed scope. Serviceability, rates, international shipping requirements, and delivery estimates depend on the selected providers and business arrangements."
      },
      {
        "q": "Can you configure GST and other tax settings?",
        "a": "We can assist with supported technical settings based on approved instructions. Tax registration, rates, invoicing, and legal compliance decisions should be confirmed with a qualified professional."
      },
      {
        "q": "Can you create variable products?",
        "a": "Yes. WooCommerce supports variable products, subject to the selected configuration. We can set up agreed attributes and variations such as sizes or colours."
      },
      {
        "q": "Can you sell digital products or subscriptions?",
        "a": "WooCommerce can support downloadable products, and specialised subscriptions or other features may be available through compatible extensions. Additional plugins, licences, and configuration may be required."
      },
      {
        "q": "Can you connect my store with Amazon or Flipkart?",
        "a": "Potentially, through suitable integrations or third-party tools. Product mapping, stock synchronisation, order routing, and ongoing operations require separate assessment and scoping."
      },
      {
        "q": "Will my store be mobile-friendly?",
        "a": "We plan responsive layouts and test the agreed pages across common device sizes. Some behaviour may depend on the selected theme, plugins, and embedded tools."
      },
      {
        "q": "Will my WooCommerce store be SEO-friendly?",
        "a": "We can configure agreed SEO-related elements, including metadata, page structure, and image alt text. These steps do not guarantee search rankings or organic traffic."
      },
      {
        "q": "Will you provide hosting and domain services?",
        "a": "These can be coordinated where agreed. Domain registration, hosting plans, renewals, and related third-party costs are separate unless explicitly included."
      },
      {
        "q": "Do you provide ongoing WooCommerce store management?",
        "a": "Yes, ongoing work can be discussed under WooCommerce Store Management. Store development alone does not include routine product updates, order handling, customer support, or ongoing optimisation."
      },
      {
        "q": "How long does development take?",
        "a": "The timeline depends on product quantity, content readiness, design complexity, payment and shipping integrations, and revision requirements. We provide an estimated timeline after confirming the scope."
      },
      {
        "q": "How much does WooCommerce store development cost?",
        "a": "The cost depends on the catalogue, page count, customisation, integrations, hosting, and required functionality. E-COMET OUTVERSE does not display public package prices on this page. We discuss your requirements and provide a custom quotation."
      }
    ],
