    "integratedSolutions": {
      "heading": "8. INTEGRATED DIGITAL SOLUTIONS",
      "headline": "Build Your Website as Part of a Bigger Digital Strategy.",
      "description": "A business website can act as the foundation for several digital activities. Depending on your goals, E-COMET OUTVERSE can help you connect website development with other relevant services.",
      "cta": "Build My Integrated Digital Plan"
    },
    "faqs": [
      {
        "q": "What is a CMS?",
        "a": "A Content Management System is software that helps users create, edit, organise and publish website content. The capabilities available depend on the selected CMS and its configuration."
      },
      {
        "q": "Which platform is best for my business?",
        "a": "There is no single best platform for every business. The recommendation depends on your website goals, content requirements, functionality, budget, integrations and ability to manage the website."
      },
      {
        "q": "Should I choose WordPress or Shopify?",
        "a": "WordPress is often considered for flexible content-led websites and can support e-commerce through WooCommerce. Shopify is primarily designed for hosted online-store operations. The right choice depends on your business model and required features."
      },
      {
        "q": "What is the difference between Shopify and WooCommerce?",
        "a": "Shopify is a hosted commerce platform. WooCommerce is an e-commerce solution built on WordPress, where hosting, updates, extensions and maintenance arrangements need to be considered as part of the overall setup."
      },
      {
        "q": "Can you help me migrate my existing website?",
        "a": "Migration can be assessed based on your current platform, content, URLs, data, integrations and technical access. Migration scope, compatibility and any limitations will be confirmed before work begins."
      },
      {
        "q": "Can you redesign my existing website without changing its platform?",
        "a": "In many cases, yes. Feasibility depends on the current platform, theme, technical condition and required changes. A platform change is not automatically necessary for every redesign."
      },
      {
        "q": "Will I be able to update my website myself?",
        "a": "Many CMS and website platforms support self-service content editing. The level of control depends on the platform and implementation. Training or handover guidance can be included in the agreed scope."
      },
      {
        "q": "Are hosting, domains and subscriptions included?",
        "a": "Not automatically. Domain registration, hosting, paid themes, apps, plugins, platform subscriptions and third-party services are listed in the proposal according to the project requirements and payment responsibilities."
      },
      {
        "q": "Can you build a custom feature?",
        "a": "Custom features are assessed individually. Some can be implemented through native platform features, extensions or supported integrations; others may require custom development or may not be feasible on the selected plan."
      },
      {
        "q": "Do you provide ongoing website maintenance?",
        "a": "Ongoing maintenance can be scoped separately, including agreed updates, backups, monitoring, troubleshooting or content changes. Availability and responsibilities will be documented in the proposal."
      },
      {
        "q": "Will the platform guarantee better SEO or more sales?",
        "a": "No platform can guarantee search rankings, traffic, leads or sales. Results depend on many factors, including content quality, technical implementation, competition, user experience, marketing and business conditions."
      },
      {
        "q": "How much does CMS and platform implementation cost?",
        "a": "Costs depend on the chosen platform, design requirements, page count, integrations, content migration and technical complexity. E-COMET OUTVERSE provides a customised quotation after understanding your requirements; public package prices are not displayed on this page."
      }
    ],
