    "integratedSolutions": {
      "heading": "8. INTEGRATED DIGITAL SOLUTIONS",
      "headline": "Build Your Website as Part of a Bigger Digital Strategy.",
      "description": "A business website can act as the foundation for several digital activities. Depending on your goals, E-COMET OUTVERSE can help you connect website development with other relevant services.",
      "cta": "Build My Integrated Digital Plan"
    },
    "faqs": [
      {
        "q": "What is website redesign?",
        "a": "Website redesign improves an existing website's visual presentation, content structure, navigation, responsiveness and selected functionality. The exact scope depends on the condition of the current website and the improvements required."
      },
      {
        "q": "What is the difference between redesign and modernization?",
        "a": "Redesign primarily focuses on the website's appearance, layout and user experience. Modernization may also include platform, technical, integration, accessibility and maintenance-related improvements."
      },
      {
        "q": "Do I need to rebuild my website from scratch?",
        "a": "Not necessarily. If the current platform and structure remain suitable, targeted improvements may be sufficient. A rebuild or migration is considered when existing limitations make the required changes impractical."
      },
      {
        "q": "Can you redesign my existing WordPress website?",
        "a": "Yes, WordPress redesign can be assessed based on your theme, plugins, current structure, technical condition and desired changes."
      },
      {
        "q": "Can you redesign Shopify or WooCommerce stores?",
        "a": "Yes, the feasibility of the redesign depends on the current theme, platform capabilities, installed apps or extensions, checkout restrictions and the required functionality."
      },
      {
        "q": "Will my website content and images be retained?",
        "a": "Existing content and images can be retained, revised, replaced or migrated according to the agreed scope and ownership permissions. Content accuracy and approval remain the client's responsibility unless content creation is separately included."
      },
      {
        "q": "Will my website's SEO rankings be affected?",
        "a": "Website changes can affect search visibility, particularly if URLs, content, navigation or technical settings change. We can include relevant SEO-conscious planning and redirect checks in the agreed scope, but rankings and traffic cannot be guaranteed."
      },
      {
        "q": "Will the redesigned website load faster?",
        "a": "We can review potential performance issues and implement agreed improvements. Actual loading speed depends on hosting, platform limitations, scripts, integrations, media and other technical factors, so a specific improvement cannot be guaranteed."
      },
      {
        "q": "Will the website work on mobile devices?",
        "a": "Responsive layouts and agreed device-size checks can be included. The final result depends on the selected platform, third-party components and the scope of testing."
      },
      {
        "q": "Can you add new features during the redesign?",
        "a": "New features can be evaluated and quoted separately if they fall outside the approved scope. Feasibility depends on the existing platform and technical requirements."
      },
      {
        "q": "Do you provide maintenance after the redesign?",
        "a": "Ongoing maintenance can be arranged as a separately defined service. Updates, backups, security checks, content changes and support responsibilities will be documented in the applicable scope."
      },
      {
        "q": "How much does website redesign cost?",
        "a": "The cost depends on the number of pages, level of customisation, platform, content changes, integrations, migration requirements and testing scope. E-COMET OUTVERSE provides a customised quotation after reviewing your requirements. Public package prices are not displayed on this page."
      }
    ],
