    "integratedSolutions": {
      "heading": "8. INTEGRATED DIGITAL SOLUTIONS",
      "headline": "Build Your Website as Part of a Bigger Digital Strategy.",
      "description": "A business website can act as the foundation for several digital activities. Depending on your goals, E-COMET OUTVERSE can help you connect website development with other relevant services.",
      "cta": "Build My Integrated Digital Plan"
    },
    "faqs": [
      {
        "q": "What is the difference between UI and UX design?",
        "a": "UI design focuses on the visual interface, including layouts, buttons, typography and interactive elements. UX design focuses on the overall experience, including navigation, usability, information flow and how easily users complete tasks."
      },
      {
        "q": "What does conversion-focused design mean?",
        "a": "It means structuring pages and interactions to make a desired action clearer and easier to complete. That action might be an enquiry, registration, quotation request or purchase."
      },
      {
        "q": "Is this service suitable for an existing website?",
        "a": "Yes. We can assess an existing website and recommend improvements to its design, navigation, content hierarchy, forms and user journeys."
      },
      {
        "q": "Do I need to redesign my entire website?",
        "a": "Not necessarily. Some businesses need changes to a few pages or interactions, while others may benefit from a broader redesign. The recommended scope depends on the issues identified and the business goals."
      },
      {
        "q": "Can you design a website before development begins?",
        "a": "Yes. Design-only projects can include agreed wireframes, page layouts, interface designs and handover materials. Development is included only when specified in the proposal."
      },
      {
        "q": "Can you improve my website's conversion rate?",
        "a": "We can review the user journey, identify potential friction points and recommend or implement appropriate improvements. A conversion-rate increase cannot be guaranteed, because outcomes depend on traffic quality, the offer, audience, technical setup and other factors."
      },
      {
        "q": "Do you provide A/B testing?",
        "a": "A/B testing can be planned or supported where the website platform, traffic volume, analytics and testing tools make it feasible. Testing setup, software costs and experiment management must be confirmed in the scope."
      },
      {
        "q": "Do you need access to my website analytics?",
        "a": "Analytics can provide useful information about user behaviour and performance. If data is available and you authorise access, it may inform recommendations. An initial design review can also be scoped without analytics, although some conclusions may be more limited."
      },
      {
        "q": "Does this service include website development?",
        "a": "Not automatically. Design, wireframing and UX recommendations can be delivered as a separate engagement. Implementation and development are included only when agreed."
      },
      {
        "q": "Can you improve an e-commerce website's shopping experience?",
        "a": "Yes. We can review product discovery, product-page structure, navigation and selected cart or checkout interactions, subject to the platform's capabilities and access permissions."
      },
      {
        "q": "How much does Design, UX & Conversion cost?",
        "a": "The cost depends on the number of pages, design complexity, research requirements, deliverables, revisions and implementation scope. E-COMET OUTVERSE provides a customised quotation after consultation; public package prices are not displayed on this page."
      }
    ],
