    "integratedSolutions": {
      "heading": "8. INTEGRATED DIGITAL SOLUTIONS",
      "headline": "Build Your Website as Part of a Bigger Digital Strategy.",
      "description": "A business website can act as the foundation for several digital activities. Depending on your goals, E-COMET OUTVERSE can help you connect website development with other relevant services.",
      "cta": "Build My Integrated Digital Plan"
    },
    "faqs": [
      {
        "q": "What does technical development and integration mean?",
        "a": "Technical development involves building or modifying website functionality. Integrations connect a website with compatible external applications or services so they can exchange data or support a defined workflow."
      },
      {
        "q": "What is an API integration?",
        "a": "An API integration uses a documented interface to allow compatible software systems to exchange information or access supported functions according to the provider's permissions and rules."
      },
      {
        "q": "Can you connect my website to a CRM?",
        "a": "We can assess and implement supported CRM connections based on the website platform, CRM capabilities, API availability, access permissions and required workflow."
      },
      {
        "q": "Can you integrate payment gateways?",
        "a": "Payment gateway configuration may be possible where the selected platform and provider support the required integration. Merchant approval, account verification, settlement and production activation remain subject to the payment provider."
      },
      {
        "q": "Can you automate website enquiry handling?",
        "a": "Yes, where the selected form, CRM, automation tool or API supports the required workflow. The scope can include field mapping, notifications, routing and agreed error handling."
      },
      {
        "q": "Can you develop custom website features?",
        "a": "Custom features can be assessed based on technical feasibility, platform restrictions, security requirements and budget. The exact deliverables are defined before implementation."
      },
      {
        "q": "Can you connect Shopify or WooCommerce to other systems?",
        "a": "Potential integrations depend on the store platform, selected apps, API access, plan limitations and the external system. We assess feasibility before committing to a particular workflow."
      },
      {
        "q": "Do you provide integrations for every third-party application?",
        "a": "Not automatically. We first check whether the application offers a suitable connector, API, documentation, permissions and technically feasible access. Some integrations may be unavailable or restricted."
      },
      {
        "q": "Will the integration work if the external platform changes its API?",
        "a": "An external provider may change its API, permissions or policies. Such changes can affect an existing integration and may require separately scoped maintenance or development."
      },
      {
        "q": "Do you provide ongoing technical support?",
        "a": "Ongoing support, monitoring, maintenance and updates can be arranged where agreed. The proposal will define support duration, response expectations and covered systems."
      },
      {
        "q": "Is my business data secure during integration?",
        "a": "Security requirements depend on the data, systems and implementation. We can discuss appropriate access controls, credential handling, data minimisation and testing within the project scope. No system should be described as completely risk-free, and formal security audits require explicit scope."
      },
      {
        "q": "How much does technical development cost?",
        "a": "Costs depend on the number of systems, API complexity, custom code, data flows, testing and external requirements. E-COMET OUTVERSE provides a customised quotation after consultation. Public package prices are not displayed on this page."
      }
    ],
