    "hero": {
      "headline": "",
      "subheadline": "",
      "description": "",
      "primaryCta": "Request a Custom Website",
      "secondaryCta": "Explore Our Development Process",
      "highlights": []
    },
    "about": {
      "title": "Digital Experiences Beyond Standard Websites",
      "paragraphs": [
        "A standard business website generally presents information about a company, its products or its services. A web application or portal can go further by allowing users to log in, access personalised information, submit requests, manage selected activities or interact with specific business functions.",
        "E-COMET OUTVERSE helps businesses explore and implement custom web applications and portals based on their objectives, operational requirements and intended users.",
        "Our approach covers requirements discovery, functionality planning, interface design, development, testing and deployment coordination within the agreed project scope.",
        "The solution may be developed using an appropriate framework, an existing platform, supported third-party tools or a combination of technologies, depending on feasibility and project needs.",
        "Our principle: Understand the required experience and workflow first. Choose the technology and functionality to fit the business objective."
      ]
    },
    "capabilities": [
      {
        "code": "01",
        "title": "Custom Web Application Development",
        "desc": "Develop browser-based applications that allow users to perform defined tasks through an interactive digital interface. Potential features include: \u25cf Custom user interfaces and application screens \u25cf Interactive forms and workflows \u25cf User account functionality \u25cf Data entry and retrieval \u25cf Application-specific business logic \u25cf User roles and permissions, where required \u25cf Connections to supported external systems \u25cf Testing and deployment planning",
        "deliverables": [],
        "benefit": [
          "Example use cases: A service-request application, an internal operations tool or a custom customer-facing digital service.",
          "The exact functionality, data model, access controls and technology stack are determined during project discovery."
        ]
      },
      {
        "code": "02",
        "title": "Customer Portal Development",
        "desc": "Create a dedicated online environment where customers can access relevant information and complete selected activities. Potential features include: \u25cf Customer login and account access \u25cf Profile and account information \u25cf Enquiry or service-request submission \u25cf Request status tracking \u25cf Access to approved documents or resources \u25cf Order or service information, where supported \u25cf Notifications and updates \u25cf Customer support workflow integration",
        "deliverables": [],
        "benefit": [
          "Customer-specific data must be protected through appropriate access controls. The availability of order information, billing details or service records depends on the underlying systems and integrations."
        ]
      },
      {
        "code": "03",
        "title": "Partner & Distributor Portals",
        "desc": "Provide authorised business partners with a dedicated digital environment for accessing relevant resources and completing agreed workflows. Potential features include: \u25cf Partner registration or invitation workflows \u25cf Partner login and access permissions \u25cf Product catalogues and approved resources \u25cf Document and training material access \u25cf Enquiry or order-request submission \u25cf Partner-specific information views \u25cf Lead or referral submission workflows \u25cf Reporting interfaces, where required",
        "deliverables": [],
        "benefit": [
          "Partner-specific pricing, inventory, order processing or commercial data requires additional business rules, appropriate permissions and supported integrations. Such features are not automatically included in a standard portal."
        ]
      },
      {
        "code": "04",
        "title": "Employee & Internal Business Portals",
        "desc": "Organise selected internal information and workflows in one controlled digital environment. Potential features include: \u25cf Employee information dashboards \u25cf Internal request forms \u25cf Document and resource libraries \u25cf Task or status tracking \u25cf Team-specific information access \u25cf Approval workflows \u25cf Internal announcements \u25cf Connections to supported business tools",
        "deliverables": [],
        "benefit": [
          "An internal portal is not automatically a complete HR, payroll, enterprise resource planning or workforce management system. Such functionality requires separate requirements analysis."
        ]
      },
      {
        "code": "05",
        "title": "Membership & Community Portals",
        "desc": "Develop a structured digital environment for members, subscribers or authorised communities. Potential features include: \u25cf Member registration and login \u25cf Member profile management \u25cf Restricted content access \u25cf Resource libraries \u25cf Membership status views \u25cf Event or activity information \u25cf Member enquiry forms \u25cf Integration with supported membership or payment services",
        "deliverables": [],
        "benefit": [
          "Recurring billing, access expiry, content protection and membership rules depend on the chosen platform and agreed technical scope."
        ]
      },
      {
        "code": "06",
        "title": "Role-Based Dashboards",
        "desc": "Give different user groups access to relevant information and functions according to their responsibilities. Potential features include: \u25cf User-specific dashboard layouts \u25cf Role-based menus and navigation \u25cf Summary cards and data tables \u25cf Selected charts and reporting views \u25cf Status indicators \u25cf Filters and search \u25cf Permission-controlled actions \u25cf Data connections where supported",
        "deliverables": [],
        "benefit": [
          "Dashboard information is only as reliable as its underlying data sources and business rules. Access permissions must be designed and tested carefully."
        ]
      },
      {
        "code": "07",
        "title": "Application Integrations & Data Connectivity",
        "desc": "Connect a custom application or portal with supported external services where a reliable integration is feasible. Potential integration areas include: \u25cf CRM systems \u25cf Website enquiry forms \u25cf E-commerce platforms \u25cf Payment providers \u25cf Booking and scheduling tools \u25cf Email and notification services \u25cf Reporting and analytics tools \u25cf Inventory or order systems \u25cf Supported APIs and webhooks",
        "deliverables": [],
        "benefit": [
          "Integrations depend on API availability, documentation, access permissions, provider terms, subscription plans and technical limitations. Third-party fees may apply."
        ]
      },
      {
        "code": "08",
        "title": "Portal Redesign & Application Modernisation",
        "desc": "Improve an existing portal or application where the interface, user experience, technology or workflows no longer meet current requirements.",
        "deliverables": [
          "Existing application review",
          "Interface and navigation improvements",
          "Mobile usability improvements",
          "Workflow simplification",
          "Selected feature enhancements",
          "Platform or framework migration assessment",
          "Integration review",
          "Testing and deployment planning"
        ],
        "benefit": [
          "Migration must account for existing functionality, data compatibility, access controls, integrations and potential downtime. A full migration or redesign is scoped separately from routine updates."
        ]
      }
    ],
