    "integratedSolutions": {
      "heading": "8. INTEGRATED DIGITAL SOLUTIONS",
      "headline": "Build Your Website as Part of a Bigger Digital Strategy.",
      "description": "A business website can act as the foundation for several digital activities. Depending on your goals, E-COMET OUTVERSE can help you connect website development with other relevant services.",
      "cta": "Build My Integrated Digital Plan"
    },
    "faqs": [
      {
        "q": "What is a custom web application?",
        "a": "A custom web application is a browser-based digital tool developed or configured around specific requirements. It may include interactive workflows, data handling, user accounts or specialised functionality beyond a typical informational website."
      },
      {
        "q": "What is a web portal?",
        "a": "A web portal provides authorised users with a structured way to access information, resources or functions. Examples include customer portals, partner portals, employee portals and membership portals."
      },
      {
        "q": "What is the difference between a website and a portal?",
        "a": "A standard website generally presents information to a broad audience. A portal typically provides a more personalised or access-controlled experience for a defined group of users. A website can contain both public pages and portal functionality."
      },
      {
        "q": "Can you develop a portal for my customers or distributors?",
        "a": "We can assess the requirements for a customer or distributor portal, including access roles, information views, workflows and integrations. The final functionality depends on technical feasibility and the agreed project scope."
      },
      {
        "q": "Can users log in and view their own information?",
        "a": "User authentication and individual information views can be included where technically suitable. The application must be designed to restrict access appropriately and protect information from unauthorised users."
      },
      {
        "q": "Can you connect a portal to my existing CRM or e-commerce system?",
        "a": "Potential integrations depend on the system's API or connector availability, permissions, subscription plan and technical limitations. We assess these factors before confirming the integration scope."
      },
      {
        "q": "Will the portal work on mobile devices?",
        "a": "Responsive interfaces can be included in the project scope. The final mobile experience depends on the selected technology, required features and testing scope."
      },
      {
        "q": "Can you migrate data from my existing application?",
        "a": "Data migration can be assessed as a separate or included project component. Feasibility depends on the source system, available exports, data quality, data structure and security requirements."
      },
      {
        "q": "Can you add features after launch?",
        "a": "Additional features can be planned as future development work, subject to the application's architecture, technical dependencies and available resources."
      },
      {
        "q": "Do you provide hosting and maintenance?",
        "a": "Hosting configuration and ongoing maintenance can be scoped according to the solution. The proposal will specify responsibility for hosting, software updates, monitoring, backups and technical support."
      },
      {
        "q": "How do you handle application security?",
        "a": "Security requirements are assessed according to the type of application, user access, data sensitivity and technical environment. Appropriate controls and testing can be scoped, but no application can be guaranteed to be completely secure."
      },
      {
        "q": "How much does a custom web application or portal cost?",
        "a": "The cost depends on the required features, number of user roles, integrations, data complexity, hosting requirements and testing needs. E-COMET OUTVERSE provides a custom quotation after consultation. Public prices are not displayed on this page."
      }
    ],
