    "integratedSolutions": {
      "heading": "8. INTEGRATED DIGITAL SOLUTIONS",
      "headline": "Build Your Website as Part of a Bigger Digital Strategy.",
      "description": "A business website can act as the foundation for several digital activities. Depending on your goals, E-COMET OUTVERSE can help you connect website development with other relevant services.",
      "cta": "Build My Integrated Digital Plan"
    },
    "faqs": [
      {
        "q": "What is website maintenance?",
        "a": "Website maintenance involves agreed recurring activities such as software updates, functionality checks, troubleshooting, backup reviews and technical upkeep. The precise scope depends on the website and service agreement."
      },
      {
        "q": "Why does a website need ongoing maintenance?",
        "a": "Websites depend on software, hosting, integrations and third-party services that can change over time. Maintenance helps businesses review these dependencies and address selected issues before they become more disruptive."
      },
      {
        "q": "Can you maintain an existing website built by another developer?",
        "a": "We can assess an existing website and determine whether it can be supported. The decision depends on platform access, code quality, licensing, documentation, technical condition and available resources."
      },
      {
        "q": "Can you improve my website's speed?",
        "a": "We can assess performance and implement suitable improvements within the agreed scope. Results depend on hosting, platform limitations, third-party scripts, architecture and other factors."
      },
      {
        "q": "Will you guarantee a specific PageSpeed score?",
        "a": "No specific score can be guaranteed before assessment. Performance tools use different testing conditions, and results may vary by page, device, network and external services."
      },
      {
        "q": "Does website security maintenance guarantee that my website cannot be hacked?",
        "a": "No. Security maintenance can help reduce certain risks, but no website can be guaranteed to be completely secure. Appropriate controls, monitoring, backups and response planning are important parts of risk management."
      },
      {
        "q": "Do you provide malware removal and hacked-website recovery?",
        "a": "Malware investigation and recovery can be assessed as separate work. The scope depends on the nature of the incident, available backups, hosting access, evidence of compromise and whether specialist incident-response support is required."
      },
      {
        "q": "Are backups included?",
        "a": "Backup checks or configuration may be included where specified in the selected plan. The proposal will define backup frequency, storage, retention, restoration testing and responsibilities."
      },
      {
        "q": "Do you provide 24/7 monitoring?",
        "a": "Monitoring and alert configuration may be available through suitable tools, but continuous monitoring, on-call response and emergency support must be explicitly included in the agreement."
      },
      {
        "q": "Can you maintain Shopify, WooCommerce and WordPress websites?",
        "a": "We can assess supported platforms and their available maintenance options. The tasks that can be performed depend on platform access, subscription restrictions, themes, plugins and third-party applications."
      },
      {
        "q": "Does maintenance include adding new pages or redesigning the website?",
        "a": "Routine maintenance may include limited agreed updates. New pages, major design changes, custom features, platform migration and substantial content work should be scoped separately unless explicitly included."
      },
      {
        "q": "How much does website maintenance cost?",
        "a": "Costs depend on the platform, website size, number of integrations, maintenance frequency, support requirements and technical complexity. E-COMET OUTVERSE provides a custom quotation after consultation. Public prices are not displayed on this page."
      }
    ],
