        "desc": "Incorrect tracking can lead to misleading reports and poor decisions. We can investigate common measurement problems within the agreed scope. Potential checks: \u25cf Duplicate tracking tags. \u25cf Missing events. \u25cf Incorrect event naming. \u25cf Cross-domain measurement issues, where relevant. \u25cf Referral attribution anomalies. \u25cf E-commerce event implementation. \u25cf Tag Manager configuration. \u25cf Consent-related measurement behaviour. \u25cf Differences between analytics and backend records. \u25cf Tracking changes following a website redesign or migration. Business value: Improve confidence in the data used for marketing and website decisions. Analytics systems may differ because of consent choices, ad blockers, attribution models, reporting thresholds, time zones, and platform processing. Exact agreement between systems cannot always be achieved.",
