    "faqs": [
      {
        "q": "What is the difference between Website Analytics and Technical SEO?",
        "a": "Website Analytics measures visitor activity and relevant website actions. Technical SEO reviews the technical factors that can affect search engine discovery, crawling, indexing, and page performance. Both can be used together to support better decisions."
      },
      {
        "q": "Do you provide Google Analytics 4 setup?",
        "a": "Yes, GA4 setup or configuration review can be included where suitable. The exact scope depends on the existing implementation, website platform, access, consent requirements, and tracking needs."
      },
      {
        "q": "Do you work with Google Search Console?",
        "a": "Yes. We can assist with setup, ownership verification, sitemap review, search performance analysis, and technical issue investigation, subject to access and website eligibility."
      },
      {
        "q": "Can you guarantee first-page Google rankings?",
        "a": "No. Search rankings depend on many factors outside any service provider's control. We focus on technical best practices, accurate measurement, and prioritised improvements without guaranteeing positions, traffic, or indexing."
      },
      {
        "q": "Will technical SEO increase my website traffic?",
        "a": "Technical improvements can address barriers that affect search accessibility and website experience, but traffic changes are not guaranteed. Results depend on competition, content relevance, demand, website quality, search engine decisions, and other factors."
      },
      {
        "q": "Do you fix the technical issues you identify?",
        "a": "Implementation can be included in Nova or Cosmic scopes, or quoted separately. An audit-only engagement provides findings and recommendations rather than automatically including every development fix."
      },
      {
        "q": "Can you improve my website's speed score?",
        "a": "We can assess performance and implement agreed improvements where technically feasible. Scores and real-user performance depend on hosting, code, themes, third-party scripts, device conditions, and other factors, so no fixed score is promised."
      },
      {
        "q": "Do you support Shopify and WooCommerce?",
        "a": "Yes, we can assess compatible analytics and technical SEO requirements for Shopify, WooCommerce, and other supported platforms. Available implementation options vary by platform, apps, theme, permissions, and subscription level."
      },
      {
        "q": "Can you track leads, WhatsApp clicks, and phone calls?",
        "a": "We can configure supported website events for these actions where technically feasible. Tracking a click is not the same as confirming that a call connected or a lead converted; additional systems may be needed for deeper attribution."
      },
      {
        "q": "Can you track e-commerce purchases and revenue?",
        "a": "Where the store platform and integrations support it, we can configure or validate product, cart, checkout, and purchase events. Accurate revenue reporting requires correct event implementation and appropriate access to the relevant systems."
      },
      {
        "q": "How long does an audit take?",
        "a": "The timeline depends on website size, platform, number of templates, technical complexity, and access. The estimated timeline and deliverables will be provided after the initial assessment."
      },
      {
        "q": "Do you need access to my website and analytics accounts?",
        "a": "Usually, yes, for implementation or detailed investigation. We request only the access needed for the agreed work and recommend role-based permissions instead of sharing personal passwords."
      },
      {
        "q": "Are analytics and SEO tools included in your service?",
        "a": "Third-party tools, paid subscriptions, premium crawlers, hosting services, and other software costs are not automatically included. Any required additional costs will be disclosed in the proposal."
      },
      {
        "q": "Can you help after a website redesign or migration?",
        "a": "Yes. We can review tracking continuity, redirects, important URLs, sitemaps, canonical tags, indexing signals, and relevant technical SEO checks before or after a migration, depending on the agreed scope."
      },
      {
        "q": "How do I choose between Orbit, Nova, and Cosmic?",
        "a": "Orbit is designed around essential setup and auditing, Nova adds deeper optimisation and selected implementation, and Cosmic supports more complex measurement and technical requirements. We will recommend a scope after understanding your website and business priorities."
      }
    ],
